package com.mfg.qms.controller;import com.mfg.common.api.ApiResponse;import com.mfg.common.service.P3CrudService;import com.mfg.qms.service.QmsLifecycleService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/qms") @RequiredArgsConstructor public class QmsP3Controller{private final P3CrudService s;private final QmsLifecycleService life;private static final java.util.Set<String>K=java.util.Set.of("standards","sampling-plans","ncrs","capas","8d");private String k(String k){if(!K.contains(k))throw new IllegalArgumentException("不支持的QMS对象");return k;}@GetMapping("/{kind}")@PreAuthorize("hasAuthority('QMS:RECORD:VIEW')")public ApiResponse<Page<Map<String,Object>>>page(@PathVariable String kind,@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.page(k(kind),keyword,status,page,size));}@GetMapping("/{kind}/{id}")@PreAuthorize("hasAuthority('QMS:RECORD:VIEW')")public ApiResponse<Map<String,Object>>detail(@PathVariable String kind,@PathVariable long id){return ApiResponse.ok(s.detail(k(kind),id));}@PostMapping("/{kind}")@PreAuthorize("hasAuthority('QMS:RECORD:CREATE')")public ApiResponse<Map<String,Object>>create(@PathVariable String kind,@RequestBody Map<String,Object>x){return ApiResponse.ok(s.create(k(kind),x));}@PostMapping("/ncrs/{id}/dispose")@PreAuthorize("hasAuthority('QMS:NCR:DISPOSE') or hasRole('ADMIN')")public ApiResponse<Map<String,Object>>dispose(@PathVariable long id,@RequestBody Map<String,String>x){return ApiResponse.ok(life.dispose(id,x.get("disposition"),x.get("reason")));}@PostMapping("/capas/{id}/verify")@PreAuthorize("hasAuthority('QMS:CAPA:VERIFY')")public ApiResponse<Map<String,Object>>verifyCapa(@PathVariable long id){return ApiResponse.ok(life.verify("capas",id));}@PostMapping("/capas/{id}/close")@PreAuthorize("hasAuthority('QMS:CAPA:CLOSE') or hasRole('ADMIN')")public ApiResponse<Map<String,Object>>closeCapa(@PathVariable long id){return ApiResponse.ok(life.close("capas",id));}@PostMapping("/8d/{id}/verify")@PreAuthorize("hasAuthority('QMS:8D:VERIFY')")public ApiResponse<Map<String,Object>>verify8d(@PathVariable long id){return ApiResponse.ok(life.verify("8d",id));}@PostMapping("/8d/{id}/close")@PreAuthorize("hasAuthority('QMS:8D:CLOSE') or hasRole('ADMIN')")public ApiResponse<Map<String,Object>>close8d(@PathVariable long id){return ApiResponse.ok(life.close("8d",id));}}
